def _classify_cve_from_description(description: str) -> Optional[tuple]:
    """Clasifica una CVE desde su texto de descripcion usando heuristica keyword.

    Devuelve (vuln_class, confidence) o None si no hay coincidencia clara.
    Confidence es un float 0-1; usar solo cuando CWE classification falla.
    NUNCA tratar como evidencia confirmada — es INFERRED.
    """
    if not description:
        return None
    desc_lower = description.lower()
    best_vc = None
    best_conf = 0.0
    for keywords, vc, confidence in _DESCRIPTION_KEYWORDS:
        if any(kw in desc_lower for kw in keywords):
            if confidence > best_conf:
                best_vc = vc
                best_conf = confidence
    if best_vc and best_conf >= 0.75:
        return (best_vc, best_conf)
    return None


def _classify_pipeline_error(error_text: str) -> dict:
    """Clasifica un error de pipeline en categoria estructurada.

    Devuelve dict con: category, stage, severity, remediation_hint.
    Permite que el feedback loop use el tipo de fallo, no solo el texto raw.
    """
    import re as _re
    err = (error_text or "").lower()
    result = {
        "category": "unknown",
        "stage": "unknown",
        "severity": "MEDIUM",
        "remediation_hint": "",
        "raw": (error_text or "")[:500],
    }

    # Stage detection
    if any(x in err for x in ("dockerfile", "build failed", "docker build", "step failed")):
        result["stage"] = "build"
    elif any(x in err for x in ("health check", "healthcheck", "container not healthy",
                                 "startup timeout", "not ready")):
        result["stage"] = "startup"
    elif any(x in err for x in ("connection refused", "econnrefused", "timeout", "no route")):
        result["stage"] = "network"
    elif any(x in err for x in ("500", "internal server error", "traceback", "exception")):
        result["stage"] = "runtime"
    elif any(x in err for x in ("verified", "diff", "baseline", "injection failed")):
        result["stage"] = "verification"

    # Category + remediation
    if _re.search(r"npm\s+(err|error|enoent|eacces)", err):
        result["category"] = "npm_install_failure"
        result["remediation_hint"] = (
            "npm install falló — verificar package.json, usar node:18-alpine, "
            "añadir --ignore-scripts si hay postinstall hook problemático")
    elif _re.search(r"apt-get|apk add|yum install", err) and "failed" in err:
        result["category"] = "pkg_install_failure"
        result["remediation_hint"] = (
            "paquete del sistema no encontrado — verificar nombre exacto, "
            "añadir apt-get update antes del install")
    elif "enospc" in err or "no space left" in err:
        result["category"] = "disk_space"
        result["severity"] = "HIGH"
        result["remediation_hint"] = "disco lleno — docker system prune para limpiar layers viejos"
    elif "port" in err and ("in use" in err or "already allocated" in err):
        result["category"] = "port_conflict"
        result["remediation_hint"] = "puerto ocupado — el lab ya usa puertos aleatorios, re-ejecutar"
    elif "connection refused" in err or "econnrefused" in err:
        result["category"] = "server_not_ready"
        result["remediation_hint"] = (
            "servidor no levantó a tiempo — añadir HEALTHCHECK en Dockerfile o "
            "incrementar HEALTH_CHECK_RETRIES en el lab")
    elif ("not found" in err and ("copy" in err or "package.json" in err or "checksum" in err)
          or "failed to calculate checksum" in err):
        result["category"] = "dockerfile_copy_missing"
        result["remediation_hint"] = (
            "COPY apunta a fichero que no existe en el contexto Docker — "
            "usar RUN npm install <pkgs> en lugar de COPY package.json; "
            "el contexto de build SOLO contiene los ficheros de extra_files")
    elif "dockerfile parse error" in err or "unknown instruction" in err:
        result["category"] = "syntax_error"
        result["remediation_hint"] = (
            "Dockerfile invalido — JSON multilínea dentro de RUN provoca que Docker "
            "interprete líneas como instrucciones; usar RUN npm install <pkgs> en su lugar")
    elif "exec format error" in err or "exec /bin/sh" in err:
        result["category"] = "dockerfile_arch"
        result["severity"] = "HIGH"
        result["remediation_hint"] = (
            "incompatibilidad de arquitectura ARM/AMD64 — añadir --platform=linux/amd64 "
            "al FROM del Dockerfile")
    elif "pull access denied" in err or "repository does not exist" in err:
        result["category"] = "image_pull_failure"
        result["severity"] = "HIGH"
        result["remediation_hint"] = (
            "imagen Docker no encontrada — verificar nombre/tag, usar node:18-alpine o python:3.11-slim")
    elif "modulenotfounderror" in err or "cannot find module" in err:
        result["category"] = "missing_dependency"
        result["remediation_hint"] = (
            "dependencia faltante — añadir al package.json o requirements.txt del lab, "
            "o instalar en RUN del Dockerfile")
    elif ("syntax" in err and ("error" in err or "unexpected" in err)):
        result["category"] = "syntax_error"
        result["remediation_hint"] = (
            "error de sintaxis en el servidor generado — revisar server.js/app.py generado por LLM")
    elif "ningun puerto publicado respondio" in err or "no published port responded" in err:
        result["category"] = "no_port_responded"
        result["stage"] = "startup"
        result["remediation_hint"] = (
            "el contenedor arranco pero NINGUN puerto publicado respondio HTTP -- lee los "
            "LOGS REALES del contenedor que van en este mismo prompt (si el proceso crasheo "
            "al iniciar, el motivo real esta ahi: traceback, modulo faltante, puerto ya en "
            "uso DENTRO del contenedor, etc.) -- no te limites a adivinar 'no hace listen en "
            "0.0.0.0' o 'falta el puerto en el CMD' sin comprobarlo contra los logs")
    elif "timeout" in err:
        result["category"] = "timeout"
        result["remediation_hint"] = (
            "timeout agotado — incrementar budget_s o simplificar el Dockerfile "
            "(evitar downloads en build time)")
    elif "permission denied" in err or "eacces" in err:
        result["category"] = "permission_denied"
        result["remediation_hint"] = (
            "permisos denegados — verificar que el directorio del lab sea escribible, "
            "o añadir USER en Dockerfile para evitar conflictos de permisos")
    elif "confirm_string not found" in err or "not found in response" in err or "secret not in" in err:
        result["category"] = "exploit_payload_miss"
        result["stage"] = "verification"
        result["remediation_hint"] = (
            "el servidor respondio pero el confirm_string NO esta en el cuerpo -- el "
            "exploit no funciona todavia: revisar el endpoint (parametro correcto, metodo "
            "HTTP, path exacto) o el payload (el servidor no ejecuta el codigo enviado). "
            "El Dockerfile puede estar bien -- el problema es la logica del exploit")
    elif _re.search(r"\b403\b|\bforbidden\b|\bauthentication required\b|\bunauthorized\b", err):
        result["category"] = "auth_required"
        result["stage"] = "verification"
        result["remediation_hint"] = (
            "el servidor devuelve 403/401 -- el endpoint requiere autenticacion. "
            "Opciones: (1) el endpoint real es distinto (buscar uno que no requiera auth), "
            "(2) añadir cabecera de bypass al lab (X-WP-Nonce, Authorization), "
            "(3) la vuln requiere una sesion previa que el lab no establece")
    elif _re.search(r"\b404\b|\bnot found\b|\bno such", err) and result["stage"] != "build":
        result["category"] = "wrong_endpoint"
        result["stage"] = "verification"
        result["remediation_hint"] = (
            "el servidor devuelve 404 -- el endpoint es incorrecto. "
            "Revisar el endpoint en las notas del CVE, "
            "o añadir una ruta alternativa al servidor generado (p.ej. /api/v2/... vs /api/...)")
    else:
        result["category"] = "generic_lab_failure"
        result["remediation_hint"] = (
            "fallo generico — ver raw error, posiblemente Dockerfile incompleto o "
            "servidor no arranca en el puerto esperado")

    return result


def _docker_self_repair(container: str, step, max_attempts: int = 3) -> bool:
    """Autonomous Docker container self-repair loop.

    Inspect the container, classify the problem, and try to fix it without
    human intervention. Returns True if the container is healthy after repair.

    Repair strategies (in order):
    1. OOMKilled / exit 137 → restart with higher memory limit
    2. Stopped / exited with code != 0 → restart container
    3. Health check failing → wait additional 30s then recheck
    4. Port not bound → inspect and find actual bound port
    5. Fatal: image missing or build failed → cannot repair, return False
    """
    import subprocess as _sp

    def _inspect(fmt: str) -> str:
        r = _sp.run(["docker", "inspect", "--format", fmt, container],
                    capture_output=True, text=True, timeout=10)
        return (r.stdout or "").strip()

    def _logs_tail() -> str:
        r = _sp.run(["docker", "logs", "--tail", "30", container],
                    capture_output=True, text=True, timeout=10)
        return ((r.stdout or "") + (r.stderr or ""))[-2000:]

    for attempt in range(1, max_attempts + 1):
        status   = _inspect("{{.State.Status}}")
        oom      = _inspect("{{.State.OOMKilled}}")
        exit_code = _inspect("{{.State.ExitCode}}")
        step(f"[self-repair #{attempt}] container={container} status={status} oom={oom} exit={exit_code}")

        if status == "running":
            # Already running — verify it's actually serving (port bound)
            port_r = _sp.run(["docker", "port", container], capture_output=True, text=True, timeout=10)
            if port_r.stdout.strip():
                step("[self-repair] container is running and has bound ports — healthy")
                return True
            # Running but no ports? Wait a bit and retry
            import time as _t; _t.sleep(5)
            continue

        if oom == "true" or exit_code == "137":
            step("[self-repair] OOMKilled (exit 137) — restarting (memory pressure)")
            _sp.run(["docker", "start", container], capture_output=True, text=True, timeout=30)
            import time as _t; _t.sleep(5)
            continue

        if status in ("exited", "dead") and exit_code not in ("", "0"):
            logs = _logs_tail()
            cls = _classify_pipeline_error(logs)
            step(f"[self-repair] container exited (code={exit_code}) category={cls['category']}: "
                 f"{cls['remediation_hint'][:120]}")
            # Structured error analysis + autonomous repair
            _err = None
            try:
                from .error_analyzer import analyze_error, render_error_summary
                _err = analyze_error(
                    stage="docker_lab", stderr=logs, exit_code=int(exit_code or 1),
                    command=f"docker container={container}", attempts=attempt,
                )
                step(f"[error_analyzer] {render_error_summary(_err)}")
            except Exception:
                pass
            # Attempt autonomous repair before giving up
            if _err is not None:
                try:
                    from .controller import execute_repair
                    _rep_ok, _rep_msg = execute_repair(
                        error=_err, cwd=os.path.expanduser("~/.binoracle"),
                        log=step, context={"container": container},
                    )
                    if _rep_ok:
                        step(f"[self-repair:auto] repair succeeded: {_rep_msg} — retrying container")
                        _sp.run(["docker", "start", container], capture_output=True, text=True, timeout=30)
                        import time as _t; _t.sleep(8)
                        continue
                except Exception:
                    pass
            if cls["category"] in ("missing_dependency", "npm_install_failure",
                                   "pkg_install_failure", "syntax_error", "build_failure"):
                step(f"[self-repair] fatal category={cls['category']} — cannot fix without rebuild")
                return False
            # Transient failure: try restart
            _sp.run(["docker", "start", container], capture_output=True, text=True, timeout=30)
            import time as _t; _t.sleep(8)
            continue

        if status == "created":
            # Container created but not started
            _sp.run(["docker", "start", container], capture_output=True, text=True, timeout=30)
            import time as _t; _t.sleep(5)
            continue

        step(f"[self-repair] unknown status={status!r} — cannot repair")
        return False

    # Final check
    final_status = _inspect("{{.State.Status}}")
    return final_status == "running"


# ═══════════════════════════════════════════════════════════════════════════════
# CONTAINER SAFETY VALIDATOR
# Valida el Dockerfile generado por el LLM antes de pasarlo al lab.
# Reglas del documento de arquitectura (sección 12).
# ═══════════════════════════════════════════════════════════════════════════════
_CONTAINER_SAFETY_VIOLATIONS = [
    # (regex_pattern, severity, description)
    (r"--privileged",        "CRITICAL", "contenedor privilegiado — deshabilitar"),
    (r"--network\s+host",    "CRITICAL", "host networking — aislar con bridge"),
    (r"network_mode.*host",  "CRITICAL", "host networking en compose"),
    (r"/var/run/docker\.sock", "HIGH",   "socket Docker montado — vector de escape"),
    (r"--cap-add\s+ALL",     "HIGH",    "todos los capabilities — especificar solo los necesarios"),
    (r"--security-opt.*seccomp:unconfined", "HIGH", "seccomp deshabilitado"),
    (r"RUN\s+curl.*\|\s*sh", "HIGH",    "pipe-to-shell — descargar y ejecutar sin verificar"),
    (r"RUN\s+wget.*\|\s*sh", "HIGH",    "pipe-to-shell — descargar y ejecutar sin verificar"),
    (r"ADD\s+http",          "MEDIUM",  "ADD desde URL externa — usar COPY + descarga separada"),
    (r"FROM\s+ubuntu:latest|FROM\s+debian:latest|FROM\s+alpine:latest",
     "INFO", "imagen sin pinning de version — usar tag especifico"),
    # Extended rules (architecture document section C)
    (r"ENV\s+\S*(PASSWORD|SECRET|TOKEN|KEY|API_KEY|PRIVATE)\s*=\s*\S+",
     "HIGH", "secreto hardcodeado en ENV — usar ARG o secreto en tiempo de ejecucion"),
    (r"USER\s+root",         "MEDIUM", "proceso corre como root — anadir USER nonroot"),
    (r"--security-opt.*apparmor:unconfined", "HIGH", "AppArmor deshabilitado"),
    (r"--cap-add\s+(SYS_ADMIN|NET_ADMIN)", "HIGH",
     "capability peligrosa — SYS_ADMIN/NET_ADMIN da acceso casi total"),
    (r"RUN\s+chmod\s+(777|a\+rwx|o\+w)",  "MEDIUM",
     "permisos excesivos chmod 777/a+rwx — usar modo minimo necesario"),
    (r"VOLUME\s+/etc\b|VOLUME\s+/proc\b|VOLUME\s+/sys\b",
     "HIGH", "volumen montando directorio de sistema critico"),
    (r"RUN\s+apt-get install.*-y.*openssh-server|RUN\s+apk add.*openssh",
     "MEDIUM", "SSH instalado en imagen de lab — superficie de ataque innecesaria"),
    (r"FROM\s+scratch\b",    "INFO",  "imagen scratch sin shell ni herramientas de debug"),
    (r"EXPOSE\s+22\b",       "MEDIUM", "puerto SSH 22 expuesto en Dockerfile de lab"),
    (r"EXPOSE\s+[0-9]{5,}",  "INFO",  "puerto de alta numeracion expuesto — verificar si es intencional"),
]


def _validate_dockerfile_safety(dockerfile_body: str, step=None) -> List[str]:
    """Verifica el Dockerfile generado por el LLM contra politica de seguridad.
    Devuelve lista de warnings con severidad, descripcion y linea aproximada.
    CRITICALs bloquean la ejecucion del lab (documentados en step).
    """
    import re as _re
    warnings: List[str] = []
    if not dockerfile_body:
        return warnings
    lines = dockerfile_body.splitlines()
    for pattern, severity, desc in _CONTAINER_SAFETY_VIOLATIONS:
        matched_line = None
        for i, line in enumerate(lines, 1):
            if _re.search(pattern, line, _re.IGNORECASE):
                matched_line = i
                break
        if matched_line is None and _re.search(pattern, dockerfile_body, _re.IGNORECASE | _re.MULTILINE):
            matched_line = 0
        if matched_line is not None:
            msg = f"[CONTAINER-SAFETY {severity}] linea~{matched_line}: {desc}"
            warnings.append(msg)
            if step and severity in ("CRITICAL", "HIGH"):
                step(f"[CONTAINER-SAFETY] {severity}: {desc}")
    return warnings


# ═══════════════════════════════════════════════════════════════════════════════
# ESCALATION HELPER — NEEDS_ANALYST
# Cuando se agotan las iteraciones del feedback loop, documenta el estado
# terminal para que el analista pueda intervenir manualmente.
# ═══════════════════════════════════════════════════════════════════════════════
def _escalate_to_analyst(inv, fail_reason: str, lab_config: dict, es: bool,
                          progress_level: str = "unknown") -> None:
    """Marca la investigacion como NEEDS_ANALYST y documenta el motivo.

    progress_level indica hasta donde llegó el pipeline:
      not_started | build_ok | start_ok | request_sent | confirm_missing
    """
    _PROGRESS_ES = {
        "not_started":    "ni siquiera inició el build Docker",
        "build_ok":       "Docker build OK pero el contenedor no arrancó",
        "start_ok":       "contenedor arrancado pero sin respuesta HTTP",
        "request_sent":   "petición HTTP enviada pero confirm_string ausente en la respuesta",
        "confirm_missing": "respuesta recibida — revisar confirm_string o payload",
        "unknown":        "estado desconocido",
    }
    _PROGRESS_EN = {
        "not_started":    "Docker build did not even start",
        "build_ok":       "Docker build OK but container did not start",
        "start_ok":       "container started but no HTTP response",
        "request_sent":   "HTTP request sent but confirm_string not in response",
        "confirm_missing": "response received — review confirm_string or payload",
        "unknown":        "unknown stage",
    }
    _prog_desc = (_PROGRESS_ES if es else _PROGRESS_EN).get(
        progress_level, progress_level)
    inv.blockers.append((
        f"[NEEDS_ANALYST] Lab autonomo agotó iteraciones sin verificar "
        f"(progreso: {_prog_desc}). "
        f"Ultimo error: {fail_reason[:300]}. "
        f"Endpoint ensayado: {lab_config.get('endpoint', 'desconocido')}. "
        f"Accion: revisar el Dockerfile/servidor generado manualmente o "
        f"proporcionar dockerfile_body/extra_files en el JSON del CVE."
        if es else
        f"[NEEDS_ANALYST] Autonomous lab exhausted iterations without verifying "
        f"(progress: {_prog_desc}). "
        f"Last error: {fail_reason[:300]}. "
        f"Endpoint tried: {lab_config.get('endpoint', 'unknown')}. "
        f"Action: review generated Dockerfile/server manually or "
        f"provide dockerfile_body/extra_files in the CVE JSON."
    ))


